import{_ as n,o as t,c as r,a2 as i}from"./chunks/framework.Buc7gXeZ.js";const c=JSON.parse('{"title":"Kanban","description":"Einträge als Karten in Spalten darstellen und per Drag & Drop verschieben.","frontmatter":{"title":"Kanban","description":"Einträge als Karten in Spalten darstellen und per Drag & Drop verschieben."},"headers":[],"relativePath":"ansichten/kanban.md","filePath":"ansichten/kanban.md","lastUpdated":1786086174000}'),a={name:"ansichten/kanban.md"};function s(l,e,o,d,u,h){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="kanban" tabindex="-1">Kanban <a class="header-anchor" href="#kanban" aria-label="Permalink to &quot;Kanban&quot;">​</a></h1><p>Ein <strong>Kanban Board</strong> zeigt Einträge als Karten in Spalten. Karten lassen sich per Drag &amp; Drop verschieben — dabei ändert sich der zugrunde liegende Feldwert.</p><p>Die Oberfläche beschreibt es als <em>Übersicht über Ihre Arbeitsprozesse</em>.</p><p><strong>Geeignet für:</strong> Abläufe mit klaren Stufen — Bewerbungen, Tickets, Aufgaben, Vertriebschancen, Freigabeprozesse.</p><h2 id="voraussetzung-eine-einzelauswahl-spalte" tabindex="-1">Voraussetzung: eine Einzelauswahl-Spalte <a class="header-anchor" href="#voraussetzung-eine-einzelauswahl-spalte" aria-label="Permalink to &quot;Voraussetzung: eine Einzelauswahl-Spalte&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Ohne Einzelauswahl kein Board</p><blockquote><p><em>Um eine Kanban Board zu sehen, muss Ihr Grid eine Spalte vom Typ Einzelauswahl besitzen. Jede Option repräsentiert eine Spalte des Kanban-Boards</em></p></blockquote><p>Fehlt eine solche Spalte, bietet ApptiveGrid <strong>Feld erstellen</strong> an, um sie direkt anzulegen.</p></div><p>Jede <strong>Option</strong> der Einzelauswahl wird zu einer <strong>Spalte</strong> des Boards. Ein Statusfeld mit <code>Neu</code>, <code>In Arbeit</code>, <code>Erledigt</code> ergibt drei Spalten.</p><div class="tip custom-block"><p class="custom-block-title">Optionen sind die Spalten — in dieser Reihenfolge</p><p>Die Reihenfolge der Spalten folgt der Reihenfolge der Optionen im Feld. Wollen Sie die Spalten umsortieren, ändern Sie die Optionsreihenfolge in den Feldeinstellungen des Grids.</p><p>Achtung: Das wirkt sich auf <strong>alle</strong> Ansichten und Formulare aus, die dieses Feld nutzen.</p></div><h2 id="board-anlegen" tabindex="-1">Board anlegen <a class="header-anchor" href="#board-anlegen" aria-label="Permalink to &quot;Board anlegen&quot;">​</a></h2><ol><li>Wählen Sie unter dem Grid <strong>Ansicht erstellen</strong>.</li><li>Wählen Sie <strong>Kanban</strong>.</li><li>Legen Sie über <strong>Gruppiert nach</strong> das Gruppierungsfeld fest.</li></ol><p>Der Auswahldialog heißt <em>Wählen Sie ein Gruppierungsfeld</em> mit dem Hinweis <em>Jede Option repräsentiert eine Spalte des Kanban-Boards</em>.</p><h2 id="karten-verschieben" tabindex="-1">Karten verschieben <a class="header-anchor" href="#karten-verschieben" aria-label="Permalink to &quot;Karten verschieben&quot;">​</a></h2><p>Ziehen Sie eine Karte in eine andere Spalte — der Wert des Gruppierungsfeldes ändert sich sofort.</p><div class="warning custom-block"><p class="custom-block-title">Das ändert echte Daten</p><p>Eine verschobene Karte ist eine geänderte Zeile im Grid. Hängt ein <a href="/docs/flows/trigger">Flow</a> mit dem Auslöser <em>Eintrag wurde geändert</em> an diesem Feld, startet er dabei.</p><p>Das ist meist gewollt — etwa eine Benachrichtigung beim Wechsel auf <code>Erledigt</code>. Beim Aufräumen eines Boards kann es aber zu unerwünschten Massenauslösungen führen.</p></div><h2 id="ungruppierte-karten" tabindex="-1">Ungruppierte Karten <a class="header-anchor" href="#ungruppierte-karten" aria-label="Permalink to &quot;Ungruppierte Karten&quot;">​</a></h2><p>Einträge ohne Wert im Gruppierungsfeld gehören zu keiner Spalte. Sie sammeln sich unter <strong>UNGRUPPIERT</strong>.</p><p>Über <strong>Ungruppierte Karten einblenden</strong> und <strong>Ungruppierte Karten ausblenden</strong> steuern Sie die Anzeige.</p><div class="tip custom-block"><p class="custom-block-title">Der Posteingang des Boards</p><p>Einträge, die über ein <a href="/docs/formulare/formular-erstellen">Formular</a> hereinkommen, haben oft noch keinen Status und landen unter <em>UNGRUPPIERT</em>. Das eignet sich gut als Eingangskorb — alles, was dort liegt, wurde noch nicht eingeordnet.</p><p>Alternativ setzen Sie im Formular einen Standardwert über <em>Vorausgefüllt</em>, damit neue Einträge gleich in der ersten Spalte erscheinen.</p></div><h2 id="einstellungen" tabindex="-1">Einstellungen <a class="header-anchor" href="#einstellungen" aria-label="Permalink to &quot;Einstellungen&quot;">​</a></h2><p>Über <strong>Einstellungen</strong>:</p><table tabindex="0"><thead><tr><th>Einstellung</th><th>Wirkung</th></tr></thead><tbody><tr><td><strong>Kartenanzahl anzeigen</strong></td><td>Zeigt je Spalte die Anzahl der Karten</td></tr><tr><td><strong>Sichtbare Spalten</strong></td><td>Blendet einzelne Spalten aus — mit <strong>Alle</strong> und <strong>Keine</strong> als Kurzwahl</td></tr></tbody></table><p>Gibt es keine Optionen, erscheint <em>Keine Spalten verfügbar</em>.</p><div class="tip custom-block"><p class="custom-block-title">Abgeschlossenes ausblenden</p><p>Bei langlebigen Boards wächst die Spalte <code>Erledigt</code> unbegrenzt. Blenden Sie sie über <em>Sichtbare Spalten</em> aus — die Einträge bleiben erhalten, das Board wird wieder übersichtlich.</p><p>Alternativ filtern Sie die Ansicht auf die letzten Wochen.</p></div><h2 id="was-auf-einer-karte-steht" tabindex="-1">Was auf einer Karte steht <a class="header-anchor" href="#was-auf-einer-karte-steht" aria-label="Permalink to &quot;Was auf einer Karte steht&quot;">​</a></h2><p>Welche Felder auf einer Karte erscheinen, konfigurieren Sie je Ansicht. Fast alle Spaltentypen haben eine eigene Darstellung auf der Karte — Text, Auswahl, Mehrfachauswahl, Häkchen, Verknüpfungen, Benutzer, Dateien, Unterschrift, Weblink, Interne Verknüpfung.</p><p>Einträge ohne Titel erscheinen als <em>Eintrag unbenannt</em>.</p><div class="tip custom-block"><p class="custom-block-title">Weniger ist mehr</p><p>Der Vorteil eines Boards ist die schnelle Erfassbarkeit. Drei bis vier Felder je Karte reichen meist: Titel, Zuständigkeit, Fälligkeit, vielleicht eine Priorität. Alles Weitere sehen Sie beim Öffnen des Eintrags.</p></div><h2 id="filter-sortierung-gruppierung" tabindex="-1">Filter, Sortierung, Gruppierung <a class="header-anchor" href="#filter-sortierung-gruppierung" aria-label="Permalink to &quot;Filter, Sortierung, Gruppierung&quot;">​</a></h2><p>Filter wirken wie in jeder Ansicht: Gefilterte Einträge erscheinen nicht auf dem Board.</p><div class="tip custom-block"><p class="custom-block-title">Ein Board je Team</p><p>Statt eines überladenen Boards lohnen sich mehrere Ansichten mit unterschiedlichen Filtern — „Mein Board&quot; mit <code>Zuständig</code> <code>ist</code> <code>angemeldeter Benutzer</code>, „Diese Woche&quot; mit einem Datumsfilter. Alle greifen auf dieselben Daten zu.</p></div><p>→ <a href="/docs/ansichten/filtern-sortieren-gruppieren">Filtern, Sortieren, Gruppieren</a></p><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/docs/ansichten/was-ist-eine-ansicht">Was ist eine Ansicht</a></li><li><a href="/docs/referenz/spaltentypen">Spaltentypen-Referenz</a></li><li><a href="/docs/ansichten/ansicht-teilen">Ansicht teilen</a></li></ul>',33)])])}const g=n(a,[["render",s]]);export{c as __pageData,g as default};
